// Compares the test-suite report this CI run wrote with the one committed in docs/ (the page the README links to)
// and warns when they differ: a cell whose verdict changed, a case or client that is new or gone, or a different
// summary (compile gate, diagnostics coverage, overall state). The committed report is regenerated by hand before a
// release (Report_EndToEndErrorBodyMatrix), so the warning says it is time.
//
// Usage: node compare-test-suite-report.mjs <committed report.json> <this run's report.json>
import { readFileSync, appendFileSync } from 'node:fs';

const [committedPath, currentPath] = process.argv.slice(2);
const read = (path) => JSON.parse(readFileSync(path, 'utf8'));
const committed = read(committedPath);
const current = read(currentPath);

// The report step failed before writing: the file is still the committed one, and there is nothing to compare
if (current.generatedAt === committed.generatedAt) {
  console.log('::warning title=No test-suite report::This run wrote no test-suite report; see the step before.');
  process.exit(0);
}

// The run compares itself with the committed history file, so its "changes" are the cells that moved since the
// committed report
const changes = current.changes ?? {};
const changed = changes.changed ?? [];
const added = changes.added ?? [];
const removed = changes.removed ?? [];

// Playwright runs in its own job; the committed report may have it and this run does not
const comparable = (report) => JSON.stringify({ ...(report.summary ?? {}), playwright: undefined });
const summaryDiffers = comparable(committed) !== comparable(current);

const reasons = [];
if (changed.length) reasons.push(`${changed.length} cell(s) changed verdict (${changed.slice(0, 5).map((c) => `${c.cell}: ${c.from} -> ${c.to}`).join('; ')}${changed.length > 5 ? '; ...' : ''})`);
if (added.length) reasons.push(`${added.length} cell(s) are new`);
if (removed.length) reasons.push(`${removed.length} cell(s) are gone`);
if (summaryDiffers) reasons.push('the summary differs (compile gate, diagnostics coverage or overall state)');

const commit = committed.provenance?.commit ?? '?';
if (reasons.length === 0) {
  console.log(`The committed test-suite report (from ${commit}) matches this run.`);
  process.exit(0);
}

const message = `The committed docs/test-suite-report.* (from ${commit}) no longer matches this run: ${reasons.join('; ')}. Regenerate it with Report_EndToEndErrorBodyMatrix before the release.`;
console.log(`::warning title=Test-suite report is out of date::${message}`);
if (process.env.GITHUB_STEP_SUMMARY) {
  appendFileSync(process.env.GITHUB_STEP_SUMMARY, `### Test-suite report is out of date\n\n${message}\n`);
}
